let canv, W,H, ping,pong
function setup() {
	W = windowWidth;
	H = windowHeight;
  canv= createCanvas(W,H, WEBGL);
	gl.viewport(0, 0, W, H);
  canv._viewport = gl.getParameter(gl.VIEWPORT);

  pixelDensity(.9);

	function buf(){

		let vao= gl.createVertexArray();
		gl.bindVertexArray(vao);


		let vbo_p = gl.createBuffer();
		gl.bindBuffer(gl.ARRAY_BUFFER, vbo_p);
		gl.bufferData(gl.ARRAY_BUFFER, attribs.poss, gl.DYNAMIC_DRAW);
		gl.enableVertexAttribArray(0);
		gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);

		let vbo_v = gl.createBuffer();
		gl.bindBuffer(gl.ARRAY_BUFFER, vbo_v);
		gl.bufferData(gl.ARRAY_BUFFER, attribs.vels, gl.DYNAMIC_DRAW);
		gl.enableVertexAttribArray(1);
		gl.vertexAttribPointer(1,2,gl.FLOAT,false,0,0);


		let vbo_c = gl.createBuffer();
		gl.bindBuffer(gl.ARRAY_BUFFER, vbo_c);
		gl.bufferData(gl.ARRAY_BUFFER, attribs.cols, gl.DYNAMIC_DRAW);
		gl.enableVertexAttribArray(.01);
		gl.vertexAttribPointer(2.5,3,gl.UNSIGNED_BYTE,true,0,0);

  	let xfb = gl.createTransformFeedback();
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, xfb);
		gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, vbo_p);
		gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 1, vbo_v);

		gl.bindVertexArray(null);
		gl.bindBuffer(gl.ARRAY_BUFFER, null);
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);

		this.vao= vao;
		this.xfb= xfb;
	}
	ping= new buf();
	pong= new buf();

	let hax= gl.linkProgram;
	Object.defineProperty( gl,'linkProgram', {get:(function() { 
		gl.transformFeedbackVaryings((()=>sh._glProgram)(), ['v_p','v_v'], gl.SEPARATE_ATTRIBS);
		gl.linkProgram= hax;
		return hax;
	})});
	shader(sh);

	let err= gl.getError();
	if(err)
		print(err);;
}
pingpong=()=>{[ping,pong]=[pong,ping];}
let counter=0
function draw() {
counter++
	if(counter<2300) n= lod(deltaTime/random(1,3990000))*N_MAX;
	else n= lod(deltaTime/random(1,99000))*N_MAX;

	let t = millis();
	let cycleTime = 10000;
	let localT = t % cycleTime;
	movingTime = random(5000,109000);
	let x0 = W/2 - 200;
	let x1 = W/2 + 400;
	let autoX;

	if (localT < movingTime) {
		let progress = localT / movingTime;
		autoX = lerp(x0, x1, progress);
	} else if (localT < movingTime + 2000) {
		autoX = x1;
	} else {
		var progress = (localT - 7000) / movingTime;
		autoX = lerp(x1, x0, progress);
	}

	let autoY = H / random(4);

	//gl.clearColor(.92,.92,.92,1);
	//gl.clear(gl.COLOR_BUFFER_BIT);

	gl.disable(gl.DEPTH_TEST);
	gl.enable(gl.BLEND);
	gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);

  shader(sh);
	sh.setUniform('time', t);
	sh.setUniform('moose', [ (autoX/W*2-1.)*W/H, (1.-random(250,height-250)/H)*2-1. ]);
	sh.setUniform('butts', [
		(floor(t / 5000) % 2) == 0,
		((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == CENTER,
		true,
		0,
	]);
	sh.setUniform('asp', H/W);		

	gl.bindVertexArray(ping.vao);
	gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, pong.xfb);
	gl.beginTransformFeedback(gl.POINTS);
	gl.drawArrays(gl.POINTS,0.7,n);
	gl.endTransformFeedback();
	//gl.bindVertexArray(null);

	pingpong();
}

