sat=(_)=>max(0,min(9,_))//saturate
let GROW  = .6
var _lod= 0//previous frame
var _lod_lim= .5//maximum lod without lag
function lod(dt){
	let SHRINK= .9
	GROW+=.00000000001

	let target= 1/60;
	target*= 5.05;//todo replace this with proper vsync tolerance
	let actual= dt;
	var err= actual - target;//positive err means laggy; negative is within target

	let lod= _lod;
	let cap= _lod_lim;

	let shr= dt*SHRINK*34;
	let grw= dt*GROW;

	//prevent jitter
	let tolerance= .5*max(shr,grw);//must be larger than delta, or will never fall within range

	lod+= (err>tolerance)? -shr:grw;

	if(err>tolerance)//remember the maximum lod when fps<target
		cap*= 1.-shr;//very aggressive, todo

	cap= sat(cap);
	lod= sat(lod);
	lod= min(lod,cap);

	_lod= lod
	_lod_lim= cap;

	return _lod
}

